["Hiçbir şey, ha? Hiçbir şey alamazsın..."] = "HİÇBİR ŞEY, HA? HİÇBİR ŞEY ALAMAZSIN...",
["Hiçbir şeyden haberleri yok."] = "HİÇBİR ŞEYDEN HABERLERİ YOK.",
["Hiçbir şeyden şüphelenmiyorlar, devam edin millet."] = "HİÇBİR ŞEYDEN ŞÜPHELENMİYORLAR, DEVAM EDİN MİLLET.",
["Hiçbir şeyden şüphelenmiyorlar. Harika."] = "HİÇBİR ŞEYDEN ŞÜPHELENMİYORLAR. HARİKA.",
["Hiçbir şeyi şansa bırakmıyorum, ekip. Gördüğünüz her kutuyu arayın. En kötü başka değerli şeyler bulursunuz."] = "HİÇBİR ŞEYİ ŞANSA BIRAKMIYORUM, EKİP. GÖRDÜĞÜNÜZ HER KUTUYU ARAYIN. EN KÖTÜ BAŞKA DEĞERLİ ŞEYLER BULURSUNUZ.",
["Hmm, araba anahtarım gerekecek."] = "HMM, ARABA ANAHTARIM GEREKECEK.",
["Hmm, birkaç zaman kilidi. Tamam, geçmek için Anahtar Kartları gerekecek. Bu kiralık güvenliklerde olmaz ama sivil araştırmacılarda olduğuna eminim. Kartları vermelerini sağlayın."] = "HMM, BİRKAÇ ZAMAN KİLİDİ. TAMAM, GEÇMEK İÇİN ANAHTAR KARTLARI GEREKECEK. BU KİRALIK GÜVENLİKLERDE OLMAZ AMA SİVİL ARAŞTIRMACILARDA OLDUĞUNA EMİNİM. KARTLARI VERMELERİNİ SAĞLAYIN.",
["Hmm, bu tasarımı tanımıyorum. Çok sıra dışı olmalı. Yakındaki tesisat odalarına bakın, bir şema bulabilecek misiniz?"] = "HMM, BU TASARIMI TANIMIYORUM. ÇOK SIRA DIŞI OLMALI. YAKINDAKİ TESİSAT ODALARINA BAKIN, BİR ŞEMA BULABİLECEK MİSİNİZ?",
["Hmm, en iyi silahların hepsini sökmüşler gibi. Alıcı için tek parça hâlinde çok daha değerli olurlar. Atölyeyi dağıtmadan önce kullansanız iyi olur."] = "HMM, EN İYİ SİLAHLARIN HEPSİNİ SÖKMÜŞLER GİBİ. ALICI İÇİN TEK PARÇA HÂLİNDE ÇOK DAHA DEĞERLİ OLURLAR. ATÖLYEYİ DAĞITMADAN ÖNCE KULLANSANIZ İYİ OLUR.",
["Hmm, evet kostik soda değil... Evet. Asit olmalı. Evet, eminim bu."] = "HMM, EVET KOSTİK SODA DEĞİL... EVET. ASİT OLMALI. EVET, EMİNİM BU.",
["Hmm, giriş güvenlik altında görünüyor. Başka bir giriş bulmanızı öneririm."] = "HMM, GİRİŞ GÜVENLİK ALTINDA GÖRÜNÜYOR. BAŞKA BİR GİRİŞ BULMANIZI ÖNERİRİM.",
["Hmm, hiçbir şey yok. Ödülümüzü burada bulmak fazla kolay olurdu herhâlde. Muhtemelen hâlâ Delil Odasında kilitli."] = "HMM, HİÇBİR ŞEY YOK. ÖDÜLÜMÜZÜ BURADA BULMAK FAZLA KOLAY OLURDU HERHÂLDE. MUHTEMELEN HÂLÂ DELİL ODASINDA KİLİTLİ.",
["Hmm, o bilgisayarda kasa dairesinin şifresinin bir kısmı vardı. Oralarda başka parçaları da olmalı."] = "HMM, O BİLGİSAYARDA KASA DAİRESİNİN ŞİFRESİNİN BİR KISMI VARDI. ORALARDA BAŞKA PARÇALARI DA OLMALI.",
["Hmm, patlayıcılar olmaz, çok tehlikeli... Bir bakayım..."] = "HMM, PATLAYICILAR OLMAZ, ÇOK TEHLİKELİ... BİR BAKAYIM...",
["Hmm, silahların bazıları sökülmüş. Alıcı için tek parça hâlinde çok daha değerli olurlar. Atölyeyi patlatmadan önce kullansanız iyi olur."] = "HMM, SİLAHLARIN BAZILARI SÖKÜLMÜŞ. ALICI İÇİN TEK PARÇA HÂLİNDE ÇOK DAHA DEĞERLİ OLURLAR. ATÖLYEYİ PATLATMADAN ÖNCE KULLANSANIZ İYİ OLUR.",
["Hmm, trenin metali çok yoğun görünüyor. Bağlantımızın depoda tutulan pürmüzlerden bahsettiğini hatırlıyorum. Onlar iş görür."] = "HMM, TRENİN METALİ ÇOK YOĞUN GÖRÜNÜYOR. BAĞLANTIMIZIN DEPODA TUTULAN PÜRMÜZLERDEN BAHSETTİĞİNİ HATIRLIYORUM. ONLAR İŞ GÖRÜR.",
["Hmm. Acaba o Domuz Kumbara daha ne kadar büyüyebilirdi..."] = "HMM. ACABA O DOMUZ KUMBARA DAHA NE KADAR BÜYÜYEBİLİRDİ...",
["Hmm. Almaya geldiğimiz kutulardan biri arşivde galiba. Oraya yürüyerek giremeyiz ama merkez alanda kullanabileceğiniz bir vinç var. Yalnız doğru rafı bulmanız gerekiyor."] = "HMM. ALMAYA GELDİĞİMİZ KUTULARDAN BİRİ ARŞİVDE GALİBA. ORAYA YÜRÜYEREK GİREMEYİZ AMA MERKEZ ALANDA KULLANABİLECEĞİNİZ BİR VİNÇ VAR. YALNIZ DOĞRU RAFI BULMANIZ GEREKİYOR.",
["Hmm... Ah, tamam! Egzoz boruları ve benzin deposu lazım. Atölyede bir tavan lifti var. Yukarıda tutuyorlar. İkisini de getirin, keyfim yerine gelsin."] = "HMM... AH, TAMAM! EGZOZ BORULARI VE BENZİN DEPOSU LAZIM. ATÖLYEDE BİR TAVAN LİFTİ VAR. YUKARIDA TUTUYORLAR. İKİSİNİ DE GETİRİN, KEYFİM YERİNE GELSİN.",
["Hmm... Bir şalter kutusu daha var galiba. Bulup diğeri gibi kablolarını değiştirin."] = "HMM... BİR ŞALTER KUTUSU DAHA VAR GALİBA. BULUP DİĞERİ GİBİ KABLOLARINI DEĞİŞTİRİN.",
["Hmm... Girişin tam nerede olduğundan emin değilim ama biraz kurcalarsanız belki bulursunuz."] = "HMM... GİRİŞİN TAM NEREDE OLDUĞUNDAN EMİN DEĞİLİM AMA BİRAZ KURCALARSANIZ BELKİ BULURSUNUZ.",
["Hmm... Haklı millet. Eşyalarını biraz dağıtıp onu kışkırtabilecek miyiz görelim."] = "HMM... HAKLI MİLLET. EŞYALARINI BİRAZ DAĞITIP ONU KIŞKIRTABİLECEK MİYİZ GÖRELİM.",
