["Hımm, umarım hava ekipmanı etkilemez. İçeride bağlantınız kesilse iyi olmaz, değil mi?"] = "HIMM, UMARIM HAVA EKİPMANI ETKİLEMEZ. İÇERİDE BAĞLANTINIZ KESİLSE İYİ OLMAZ, DEĞİL Mİ?",
["Hımm. Belki güvenlikten geçmekten daha iyi bir giriş yolu vardır."] = "HIMM. BELKİ GÜVENLİKTEN GEÇMEKTEN DAHA İYİ BİR GİRİŞ YOLU VARDIR.",
["Hımm... Acaba soru işareti ne demek?"] = "HIMM... ACABA SORU İŞARETİ NE DEMEK?",
["Hımm... Burada olamaz... Orada da değil..."] = "HIMM... BURADA OLAMAZ... ORADA DA DEĞİL...",
