["Hımm... O gerçekten sunucu muydu bilmiyorum... "] = "HIMM... O GERÇEKTEN SUNUCU MUYDU BİLMİYORUM... ",
["Hımm... Tamam, görüyorum. İşimize dönelim."] = "HIMM... TAMAM, GÖRÜYORUM. İŞİMİZE DÖNELİM.",
