["Jiu Feng'e işaret vermek için havai fişekleri patlatmanız gerek!"] = "JIU FENG'E İŞARET VERMEK İÇİN HAVAİ FİŞEKLERİ PATLATMANIZ GEREK!",
["Jiu Feng'e ulaşamıyorum. Parazit var. Böyle olabileceğini biliyorduk, o yüzden işaretinizi bekliyor. Benzin gibi yanıcı bir şey bulun... İşaret ateşi yakın."] = "JIU FENG'E ULAŞAMIYORUM. PARAZİT VAR. BÖYLE OLABİLECEĞİNİ BİLİYORDUK, O YÜZDEN İŞARETİNİZİ BEKLİYOR. BENZİN GİBİ YANICI BİR ŞEY BULUN... İŞARET ATEŞİ YAKIN.",
["Jiu Feng'i bekle ve ip merdiveni aç"] = "JIU FENG'İ BEKLE VE İP MERDİVENİ AÇ",
["Jiu Feng'in adamı bir yerde barmenlik yapıyor. Gidip bulalım, ne diyecekmiş bakalım."] = "JIU FENG'İN ADAMI BİR YERDE BARMENLİK YAPIYOR. GİDİP BULALIM, NE DİYECEKMİŞ BAKALIM.",
["Jiu Feng'in adamı güncel bilgileri bir evrak çantasına koyup kabin banyolarından birine saklayacaktı. Gidip bulalım, ha?"] = "JIU FENG'İN ADAMI GÜNCEL BİLGİLERİ BİR EVRAK ÇANTASINA KOYUP KABİN BANYOLARINDAN BİRİNE SAKLAYACAKTI. GİDİP BULALIM, HA?",
["Jiu Feng'in adamı mürettebat güvertesindeki depoya size fazladan ekipman bırakmış olmalı. Gidip alın, çabuk çabuk!"] = "JIU FENG'İN ADAMI MÜRETTEBAT GÜVERTESİNDEKİ DEPOYA SİZE FAZLADAN EKİPMAN BIRAKMIŞ OLMALI. GİDİP ALIN, ÇABUK ÇABUK!",
["Jiu Feng'in adamı, kumarhanede bir yerde bir bakım kutusunu açtırdı. Kesmemiz için açıkta bir kablo bırakıldı."] = "JIU FENG'İN ADAMI, KUMARHANEDE BİR YERDE BİR BAKIM KUTUSUNU AÇTIRDI. KESMEMİZ İÇİN AÇIKTA BİR KABLO BIRAKILDI.",
["Jiu Feng'in adamına size bir C4 sürprizi bıraktırdım. Onunla kasa dairesinin tamamını patlatıp yanımızda götürelim. Kesin harika olacak!"] = "JIU FENG'İN ADAMINA SİZE BİR C4 SÜRPRİZİ BIRAKTIRDIM. ONUNLA KASA DAİRESİNİN TAMAMINI PATLATIP YANIMIZDA GÖTÜRELİM. KESİN HARİKA OLACAK!",
["Jiu Feng'in bahsettiği bir şey şimdi aklıma geldi... O bariyerleri geçmeden yapmamız gereken bir şey."] = "JIU FENG'İN BAHSETTİĞİ BİR ŞEY ŞİMDİ AKLIMA GELDİ... O BARİYERLERİ GEÇMEDEN YAPMAMIZ GEREKEN BİR ŞEY.",
["Jiu Feng'in gelip sizi alması biraz sürecek. Sıkı durun!"] = "JIU FENG'İN GELİP SİZİ ALMASI BİRAZ SÜRECEK. SIKI DURUN!",
["Jiu Feng'in içerideki adamına mini yükleyiciyi hangi yoldan götüreceğini göstermek için yollardan birini aç."] = "JIU FENG'İN İÇERİDEKİ ADAMINA MİNİ YÜKLEYİCİYİ HANGİ YOLDAN GÖTÜRECEĞİNİ GÖSTERMEK İÇİN YOLLARDAN BİRİNİ AÇ.",
["Jiu Feng'in teknesi mi o? Güzel, binin, çabuk çabuk!"] = "JIU FENG'İN TEKNESİ Mİ O? GÜZEL, BİNİN, ÇABUK ÇABUK!",
["Jiu Feng'le bağlantım kesildi. Triad sinyalimizi bozuyor olabilir. Yakın zamanda buraya kaçak havai fişek sevkiyatı gelmişti. Patlatırsanız gelip sizi alması için harika işaret olur!"] = "JIU FENG'LE BAĞLANTIM KESİLDİ. TRİAD SİNYALİMİZİ BOZUYOR OLABİLİR. YAKIN ZAMANDA BURAYA KAÇAK HAVAİ FİŞEK SEVKİYATI GELMİŞTİ. PATLATIRSANIZ GELİP SİZİ ALMASI İÇİN HARİKA İŞARET OLUR!",
["Jiu Feng'le bağlantıyı korumakta zorlanıyorum. Telsizde çok parazit var; Wang denen o herif hâlâ bir şeyler çeviriyor olabilir. Sizi almaları için işaret vermeniz gerekecek. Triad buradan çok havai fişek kaçırıyor, belki birkaç tane bulursunuz."] = "JIU FENG'LE BAĞLANTIYI KORUMAKTA ZORLANIYORUM. TELSİZDE ÇOK PARAZİT VAR; WANG DENEN O HERİF HÂLÂ BİR ŞEYLER ÇEVİRİYOR OLABİLİR. SİZİ ALMALARI İÇİN İŞARET VERMENİZ GEREKECEK. TRİAD BURADAN ÇOK HAVAİ FİŞEK KAÇIRIYOR, BELKİ BİRKAÇ TANE BULURSUNUZ.",
["Jiu Feng'le telsiz bağlantım şu an kesik, ona ateşle işaret vermeniz gerekecek. Etrafta ateş yakmak için ne kullanabilirsiniz bakın."] = "JIU FENG'LE TELSİZ BAĞLANTIM ŞU AN KESİK, ONA ATEŞLE İŞARET VERMENİZ GEREKECEK. ETRAFTA ATEŞ YAKMAK İÇİN NE KULLANABİLİRSİNİZ BAKIN.",
["Jiu Feng, San Francisco merkezli bir silah tüccarıdır. Bir zamanlar güçlü Golden Dagger Triad örgütünün üyesiydi ama lideri Yufu Wang'ın gözünden düşünce ayrıldı. Yine de Triad'ın faaliyetlerini yakından tanır."] = "JIU FENG, SAN FRANCISCO MERKEZLİ BİR SİLAH TÜCCARIDIR. BİR ZAMANLAR GÜÇLÜ GOLDEN DAGGER TRIAD ÖRGÜTÜNÜN ÜYESİYDİ AMA LİDERİ YUFU WANG'IN GÖZÜNDEN DÜŞÜNCE AYRILDI. YİNE DE TRİAD'IN FAALİYETLERİNİ YAKINDAN TANIR.",
["Jiu Feng, triad'ın liman ofisinde birçok operasyonel bilgi tuttuğunu söyledi. Bakmaya değer olabilir."] = "JIU FENG, TRİAD'IN LİMAN OFİSİNDE BİRÇOK OPERASYONEL BİLGİ TUTTUĞUNU SÖYLEDİ. BAKMAYA DEĞER OLABİLİR.",
