["Kasa Alanı"] = "KASA ALANI",
["Kasa Açma Planı"] = "KASA AÇMA PLANI",
["Kasa Dairelerinin açılması biraz sürer. Güvenlik önlemi. Güvenlik önemlidir, bilirsiniz."] = "KASA DAİRELERİNİN AÇILMASI BİRAZ SÜRER. GÜVENLİK ÖNLEMİ. GÜVENLİK ÖNEMLİDİR, BİLİRSİNİZ.",
["Kasa Dairesi"] = "KASA DAİRESİ",
["Kasa Dairesi açık. Bu numara neredeyse bitti. Biraz para çantalayın!"] = "KASA DAİRESİ AÇIK. BU NUMARA NEREDEYSE BİTTİ. BİRAZ PARA ÇANTALAYIN!",
