["Kasa Dairesi açıldı. Paraları yığmaya başlayın, ekip."] = "KASA DAİRESİ AÇILDI. PARALARI YIĞMAYA BAŞLAYIN, EKİP.",
["Kasa Dairesi açıldı. İçinde ne varsa alın, ekip!"] = "KASA DAİRESİ AÇILDI. İÇİNDE NE VARSA ALIN, EKİP!",
["Kasa Dairesi bankanın arka taraflarının derinliklerinde. Ulaşmak zor olacak ama yardımımız var. İçerideki adamımız hazır, sizi bekliyor. İçeri girdiğinizde bize yardım edecek. Gürültülü yapabilir ya da sessizce ilerleyebilirsiniz. Size kalmış."] = "KASA DAİRESİ BANKANIN ARKA TARAFLARININ DERİNLİKLERİNDE. ULAŞMAK ZOR OLACAK AMA YARDIMIMIZ VAR. İÇERİDEKİ ADAMIMIZ HAZIR, SİZİ BEKLİYOR. İÇERİ GİRDİĞİNİZDE BİZE YARDIM EDECEK. GÜRÜLTÜLÜ YAPABİLİR YA DA SESSİZCE İLERLEYEBİLİRSİNİZ. SİZE KALMIŞ.",
["Kasa Dairesi bu Murkywater nakliye konteynerlerinden birinde olacak. Kontrol edin!"] = "KASA DAİRESİ BU MURKYWATER NAKLİYE KONTEYNERLERİNDEN BİRİNDE OLACAK. KONTROL EDİN!",
["Kasa Dairesi bölgesindeki gözlerini oydunuz. Orada artık kamera yok."] = "KASA DAİRESİ BÖLGESİNDEKİ GÖZLERİNİ OYDUNUZ. ORADA ARTIK KAMERA YOK.",
["Kasa Dairesi bölgesindeki son kamera da tamam. İyi iş."] = "KASA DAİRESİ BÖLGESİNDEKİ SON KAMERA DA TAMAM. İYİ İŞ.",
["Kasa Dairesi hiçbir yere gitmiyor. Anahtar Kartı'yla şifreyi bekliyor."] = "KASA DAİRESİ HİÇBİR YERE GİTMİYOR. ANAHTAR KARTI'YLA ŞİFREYİ BEKLİYOR.",
["Kasa Dairesi için gereken üç hanenin hepsi elimizde. Oraya gidip kodu girin."] = "KASA DAİRESİ İÇİN GEREKEN ÜÇ HANENİN HEPSİ ELİMİZDE. ORAYA GİDİP KODU GİRİN.",
["Kasa Dairesi kendi kendine açılmayacak..."] = "KASA DAİRESİ KENDİ KENDİNE AÇILMAYACAK...",
["Kasa Dairesi kesinlikle bu."] = "KASA DAİRESİ KESİNLİKLE BU.",
["Kasa Dairesi kumarhanenin tam ortasında."] = "KASA DAİRESİ KUMARHANENİN TAM ORTASINDA.",
["Kasa Dairesi oldukça yakın. Gidip bulalım, ha?"] = "KASA DAİRESİ OLDUKÇA YAKIN. GİDİP BULALIM, HA?",
["Kasa Dairesi para dolu gibi. Ne kadarını alıp kaçacağınız size kalmış."] = "KASA DAİRESİ PARA DOLU GİBİ. NE KADARINI ALIP KAÇACAĞINIZ SİZE KALMIŞ.",
["Kasa Dairesi yumurta gibi çatlamalı!"] = "KASA DAİRESİ YUMURTA GİBİ ÇATLAMALI!",
["Kasa Dairesi şifresinin ilk hanesi. Aramaya devam edin. Üçü de lazım."] = "KASA DAİRESİ ŞİFRESİNİN İLK HANESİ. ARAMAYA DEVAM EDİN. ÜÇÜ DE LAZIM.",
["Kasa Dairesi!"] = "KASA DAİRESİ!",
["Kasa Dairesi'nde aynı anda kullanılması gereken iki kart okuyucu var. Muhtemelen 10 saniyelik zaman kilidi de vardır. İçeride güzel bir şeyler saklıyor olmalılar."] = "KASA DAİRESİ'NDE AYNI ANDA KULLANILMASI GEREKEN İKİ KART OKUYUCU VAR. MUHTEMELEN 10 SANİYELİK ZAMAN KİLİDİ DE VARDIR. İÇERİDE GÜZEL BİR ŞEYLER SAKLIYOR OLMALILAR.",
["Kasa Dairesi'ne bir bakın. Af belgelerimizin orada tutulduğundan oldukça eminim."] = "KASA DAİRESİ'NE BİR BAKIN. AF BELGELERİMİZİN ORADA TUTULDUĞUNDAN OLDUKÇA EMİNİM.",
["Kasa Dairesi'ne erişim kapatıldı. Girmek için kontrol panelini hacklemelisiniz. Yakında olmalı."] = "KASA DAİRESİ'NE ERİŞİM KAPATILDI. GİRMEK İÇİN KONTROL PANELİNİ HACKLEMELİSİNİZ. YAKINDA OLMALI.",
["Kasa Dairesi'ne gidin."] = "KASA DAİRESİ'NE GİDİN.",
["Kasa Dairesi'ne girmek için Deng'in şifresiyle Kang'ın el izi gerekecek. "] = "KASA DAİRESİ'NE GİRMEK İÇİN DENG'İN ŞİFRESİYLE KANG'IN EL İZİ GEREKECEK. ",
["Kasa Dairesi'ni açmak için Deng'in şifresini ve Kang'ın el izini almalısınız, tamam mı?"] = "KASA DAİRESİ'Nİ AÇMAK İÇİN DENG'İN ŞİFRESİNİ VE KANG'IN EL İZİNİ ALMALISINIZ, TAMAM MI?",
["Kasa Dairesi'ni açmak için eli ve şifreyi kullanın!"] = "KASA DAİRESİ'Nİ AÇMAK İÇİN ELİ VE ŞİFREYİ KULLANIN!",
["Kasa Dairesi'ni açmak için şifre ve Anahtar Kartı gerekiyor. Aramaya başlayın."] = "KASA DAİRESİ'Nİ AÇMAK İÇİN ŞİFRE VE ANAHTAR KARTI GEREKİYOR. ARAMAYA BAŞLAYIN.",
["Kasa Dairesi'ni açmak üzereyim. Bekleyin."] = "KASA DAİRESİ'Nİ AÇMAK ÜZEREYİM. BEKLEYİN.",
["Kasa Dairesi'ni açmalıyız. Ya Anahtar Kartları'yla sessizce ya da matkapla zorlayarak."] = "KASA DAİRESİ'Nİ AÇMALIYIZ. YA ANAHTAR KARTLARI'YLA SESSİZCE YA DA MATKAPLA ZORLAYARAK.",
["Kasa Dairesi'ni gazla dolduruyorlar! Hiç sorunsuz gitmiyor, değil mi? Gaz dağılana kadar beklemeniz gerekecek."] = "KASA DAİRESİ'Nİ GAZLA DOLDURUYORLAR! HİÇ SORUNSUZ GİTMİYOR, DEĞİL Mİ? GAZ DAĞILANA KADAR BEKLEMENİZ GEREKECEK.",
["Kasa Dairesi'ni hâlâ bulamadınız mı?"] = "KASA DAİRESİ'Nİ HÂLÂ BULAMADINIZ MI?",
["Kasa Dairesi'ni termal matkapla açın. Sonra kiralık Kasaları açın, testere isteyebilirsiniz. Ardından ganimeti kaçış minibüsüne taşıyın."] = "KASA DAİRESİ'Nİ TERMAL MATKAPLA AÇIN. SONRA KİRALIK KASALARI AÇIN, TESTERE İSTEYEBİLİRSİNİZ. ARDINDAN GANİMETİ KAÇIŞ MİNİBÜSÜNE TAŞIYIN.",
["Kasa Dairesi'nin bu kadar kalın olmasını beklemiyordum. Başka yolu yok, delmeniz gerekecek. Bir matkap hazır bekliyor."] = "KASA DAİRESİ'NİN BU KADAR KALIN OLMASINI BEKLEMİYORDUM. BAŞKA YOLU YOK, DELMENİZ GEREKECEK. BİR MATKAP HAZIR BEKLİYOR.",
["Kasa Dairesi'nin etrafına C4 döşeyin, patlatıp yerinden kurtaralım!"] = "KASA DAİRESİ'NİN ETRAFINA C4 DÖŞEYİN, PATLATIP YERİNDEN KURTARALIM!",
["Kasa Dairesi'nin hemen üstündeki odaya girip termiti dökün."] = "KASA DAİRESİ'NİN HEMEN ÜSTÜNDEKİ ODAYA GİRİP TERMİTİ DÖKÜN.",
["Kasa Dairesi'nin içindeki kapıların anahtarları bunlar. İyi buldunuz."] = "KASA DAİRESİ'NİN İÇİNDEKİ KAPILARIN ANAHTARLARI BUNLAR. İYİ BULDUNUZ.",
["Kasa Dairesi'nin kapılarını polisler kontrol ediyor. Her an açılacaklar, hazır olun!"] = "KASA DAİRESİ'NİN KAPILARINI POLİSLER KONTROL EDİYOR. HER AN AÇILACAKLAR, HAZIR OLUN!",
["Kasa Dairesi'nin kapısına dönüp sabit diski takın. Gerisini ben hallederim."] = "KASA DAİRESİ'NİN KAPISINA DÖNÜP SABİT DİSKİ TAKIN. GERİSİNİ BEN HALLEDERİM.",
