["Lanet olsun! O aracı yoldan çekmelisiniz!"] = "LANET OLSUN! O ARACI YOLDAN ÇEKMELİSİNİZ!",
["Lanet olsun! O boklar kabloyu kesti. Tamir edin!"] = "LANET OLSUN! O BOKLAR KABLOYU KESTİ. TAMİR EDİN!",
