["Lanet olsun, yukarıda yangın var. Kabindeki sen! Hallet!"] = "LANET OLSUN, YUKARIDA YANGIN VAR. KABİNDEKİ SEN! HALLET!",
["Lanet olsun, çok yaklaşmıştık!"] = "LANET OLSUN, ÇOK YAKLAŞMIŞTIK!",
["Lanet olsun, şarj durdu. Yeniden başlatın, tamam mı?"] = "LANET OLSUN, ŞARJ DURDU. YENİDEN BAŞLATIN, TAMAM MI?",
["Lanet olsun, şişko sıçan asansörde. Peşine düşün! Kaçmadan yakalayın!"] = "LANET OLSUN, ŞİŞKO SIÇAN ASANSÖRDE. PEŞİNE DÜŞÜN! KAÇMADAN YAKALAYIN!",
["Lanet olsun, şu mekâna bakın. Adamın tarzı var. Sessizce ya da gümbür gümbür yapabilirsiniz, seçim sizin."] = "LANET OLSUN, ŞU MEKÂNA BAKIN. ADAMIN TARZI VAR. SESSİZCE YA DA GÜMBÜR GÜMBÜR YAPABİLİRSİNİZ, SEÇİM SİZİN.",
["Lanet olsun, şu ucuz, boktan Rus karıştırıcısı çöktü. Yeniden çalıştırın."] = "LANET OLSUN, ŞU UCUZ, BOKTAN RUS KARIŞTIRICISI ÇÖKTÜ. YENİDEN ÇALIŞTIRIN.",
["Lanet olsun, şunu dinleyin. Buluc'un güvenlikçileri, malikânedeki bilgisayardan dört özel maske sipariş edecek kadar dikkatsizmiş. Faturayı bulun da maskeleri tanıyabilelim."] = "LANET OLSUN, ŞUNU DİNLEYİN. BULUC'UN GÜVENLİKÇİLERİ, MALİKÂNEDEKİ BİLGİSAYARDAN DÖRT ÖZEL MASKE SİPARİŞ EDECEK KADAR DİKKATSİZMİŞ. FATURAYI BULUN DA MASKELERİ TANIYABİLELİM.",
["Lanet olsun, şüphelendiğim gibi. Sadece patlayıcıyla oraya giremezsiniz ama bir planım var."] = "LANET OLSUN, ŞÜPHELENDİĞİM GİBİ. SADECE PATLAYICIYLA ORAYA GİREMEZSİNİZ AMA BİR PLANIM VAR.",
["Lanet olsun. B planına geçin."] = "LANET OLSUN. B PLANINA GEÇİN.",
["Lanet olsun. Eşleşme yok. Aramaya devam!"] = "LANET OLSUN. EŞLEŞME YOK. ARAMAYA DEVAM!",
["Lanet olsun. Kilitli. Hımm. Tamam. Müdür hâlâ orada. Rehin alın. Kilit hakkında bilgisi var mı bakın."] = "LANET OLSUN. KİLİTLİ. HIMM. TAMAM. MÜDÜR HÂLÂ ORADA. REHİN ALIN. KİLİT HAKKINDA BİLGİSİ VAR MI BAKIN.",
["Lanet olsun. Peki. Misafirlerimiz olacak millet."] = "LANET OLSUN. PEKİ. MİSAFİRLERİMİZ OLACAK MİLLET.",
["Lanet olsun. Takasa yetecek malımız yok, zor durumdayız demek. Sessizce Hector'a gidelim. Bakalım ne olacak."] = "LANET OLSUN. TAKASA YETECEK MALIMIZ YOK, ZOR DURUMDAYIZ DEMEK. SESSİZCE HECTOR'A GİDELİM. BAKALIM NE OLACAK.",
["Lanet olsun. Şimdi sancılı yoldan gidiyoruz."] = "LANET OLSUN. ŞİMDİ SANCILI YOLDAN GİDİYORUZ.",
["Lanet olsun... Bu kötü..."] = "LANET OLSUN... BU KÖTÜ...",
["Lanet olsun... Yeterince gizli değildik. O kamyondaki GPS artık anlamsız. Bundan sonra çok dikkatli davranıp oy makinelerinin rotasını falan değiştirecekler. Onlara ulaşmanın bir yolunu bulmalıyız."] = "LANET OLSUN... YETERİNCE GİZLİ DEĞİLDİK. O KAMYONDAKİ GPS ARTIK ANLAMSIZ. BUNDAN SONRA ÇOK DİKKATLİ DAVRANIP OY MAKİNELERİNİN ROTASINI FALAN DEĞİŞTİRECEKLER. ONLARA ULAŞMANIN BİR YOLUNU BULMALIYIZ.",
["Lanet otoparka mayın döşüyorlar millet! Dışarıda dikkatli olun."] = "LANET OTOPARKA MAYIN DÖŞÜYORLAR MİLLET! DIŞARIDA DİKKATLİ OLUN.",
["Lanet palyaçolar, burada olmamalısınız!"] = "LANET PALYAÇOLAR, BURADA OLMAMALISINIZ!",
["Lanet park yeri, çıkalım buradan."] = "LANET PARK YERİ, ÇIKALIM BURADAN.",
["Lanet parmak izi tarayıcısı. Tamam, kimde bant var? Kimsede bant var mı? Müdürün bir eşyadaki parmak izini bantla alıp o zımbırtıyı fazla gürültü çıkarmadan açabilirsiniz."] = "LANET PARMAK İZİ TARAYICISI. TAMAM, KİMDE BANT VAR? KİMSEDE BANT VAR MI? MÜDÜRÜN BİR EŞYADAKİ PARMAK İZİNİ BANTLA ALIP O ZIMBIRTIYI FAZLA GÜRÜLTÜ ÇIKARMADAN AÇABİLİRSİNİZ.",
["Lanet polis pususu bu!"] = "LANET POLİS PUSUSU BU!",
["Lanet polisler bilişimciye ulaşıp kilidi açmasını durdurdu. Girip işini bitirtin!"] = "LANET POLİSLER BİLİŞİMCİYE ULAŞIP KİLİDİ AÇMASINI DURDURDU. GİRİP İŞİNİ BİTİRTİN!",
["Lanet polisler elektriği kesti! Açmanın bir yolunu bulun!"] = "LANET POLİSLER ELEKTRİĞİ KESTİ! AÇMANIN BİR YOLUNU BULUN!",
["Lanet polisler elektriği kesti, yeniden açın!"] = "LANET POLİSLER ELEKTRİĞİ KESTİ, YENİDEN AÇIN!",
["Lanet polisler kapıda. Hazır olun!"] = "LANET POLİSLER KAPIDA. HAZIR OLUN!",
