["Lanet polisler orada olacağımızı biliyordu. Basit bir elmas işi için sayıları çok fazlaydı. Siviller de vardı."] = "LANET POLİSLER ORADA OLACAĞIMIZI BİLİYORDU. BASİT BİR ELMAS İŞİ İÇİN SAYILARI ÇOK FAZLAYDI. SİVİLLER DE VARDI.",
["Lanet polisler yönlendirici kutularının elektriğini kesmeye çalışıyor! Durdurun onları!"] = "LANET POLİSLER YÖNLENDİRİCİ KUTULARININ ELEKTRİĞİNİ KESMEYE ÇALIŞIYOR! DURDURUN ONLARI!",
["Lanet polisler!"] = "LANET POLİSLER!",
["Lanet polisler! "] = "LANET POLİSLER! ",
