["Lanet sersemler devre atlatma işlemini durdurdu, yeniden çalıştırın."] = "LANET SERSEMLER DEVRE ATLATMA İŞLEMİNİ DURDURDU, YENİDEN ÇALIŞTIRIN.",
["Lanet sinyal bozucu yine durdu. Tamir edin!"] = "LANET SİNYAL BOZUCU YİNE DURDU. TAMİR EDİN!",
["Lanet takım elbiseliler..."] = "LANET TAKIM ELBİSELİLER...",
