["Lanet! Çatıya ilerlemelisiniz ama tuş takımı devre dışı. Bana bir yöneticinin bilgisayarını bulun."] = "LANET! ÇATIYA İLERLEMELİSİNİZ AMA TUŞ TAKIMI DEVRE DIŞI. BANA BİR YÖNETİCİNİN BİLGİSAYARINI BULUN.",
["Lanet! Çelik halat artık işe yaramaz. Onunla ganimet göndermeyi unutun!"] = "LANET! ÇELİK HALAT ARTIK İŞE YARAMAZ. ONUNLA GANİMET GÖNDERMEYİ UNUTUN!",
["Lanet! İyi misiniz?"] = "LANET! İYİ MİSİNİZ?",
